 "staff": [
  {
   "id": "a1",
   "name": "أ/ فهد العجمي",
   "role": "مدير المدرسة",
   "msg": "يسعدني أن أقدّم لأبنائي الطلاب هذه المنصة التي تجسّد حرص مدرستنا على توظيف التقنية في خدمة التعليم. إنّ تحويل المفاهيم المجرّدة إلى نماذج محسوسة يُسهم في ترسيخ الفهم وتنمية حب العلم في نفوس طلابنا.\n\nأشكر كل من أسهم في هذا العمل، وأسأل الله أن ينفع بها الجميع.",
   "photo": "",
   "cat": "admin",
   "subject": "",
   "email": ""
  },
  {
   "id": "tfr7rpt",
   "photo": "",
   "name": "أ/ عطاف العنزي",
   "cat": "guide",
   "role": "المراقب الفني للعلوم",
   "subject": "",
   "email": "",
   "msg": "يسرّني أن أبارك هذه المبادرة التي تنسجم مع توجّهات تطوير تعليم العلوم، من خلال توظيف المحاكاة التفاعلية في تقريب المفاهيم العلمية للمتعلمين وتعزيز مهارات الاستقصاء والتفكير العلمي لديهم.\n\nأشكر القائمين على هذا العمل، وأتمنى أن يكون نموذجًا يُحتذى به في دعم التعلم الرقمي في مادة الكيمياء."
  },
  {
   "id": "a2",
   "name": "أ/ مشاعل المطيري",
   "role": "موجه الكيمياء",
   "msg": "أبنائي الطلاب، نماذج المحاكاة وسيلة لتروا التفاعلات الكيميائية وتجرّبوها بأنفسكم بأمان، وتربطوا ما تدرسونه في الكتاب بما يحدث فعلًا في عالم المادة.\n\nأدعوكم إلى استثمارها بالتجربة والسؤال وإعادة المحاولة، فالفهم الحقيقي يبدأ بالتجربة. \n\nوأتمنى لكم التوفيق والتفوق.",
   "photo": "",
   "cat": "guide",
   "subject": "",
   "email": ""
  },
  {
   "id": "n0nmcqv",
   "photo": "",
   "name": "أ/ أبو يعقوب",
   "cat": "admin",
   "role": "المدير المساعد",
   "subject": "",
   "email": "",
   "msg": "أبنائي الطلاب، تأتي هذه المنصة لتكون رفيقكم في الدراسة والمراجعة في أي وقت. استفيدوا من نماذجها، والتزموا بالمذاكرة المنتظمة، فالنجاح ثمرة الجد والاجتهاد."
  },
  {
   "id": "5k4jbgq",
   "photo": "",
   "name": "أ/ عمرو عاطف",
   "cat": "teacher",
   "role": "رئيس قسم الكيمياء والفيزياء",
   "subject": "",
   "email": "",
   "msg": "أبنائي الطلاب، زملائي المعلمين،\n\nيسعدني أن أقدّم هذه المنصة التي تعبّر عن روح العمل الجماعي في قسمنا، وعن إيماننا بأن العلم يُفهم بالتجربة والمشاهدة قبل الحفظ. فنماذج المحاكاة تتيح للطالب أن يجرّب ويلاحظ ويستنتج بأمان، وتساعد المعلم على تقريب المفاهيم الكيميائية المجرّدة.\n\nأدعو أبنائي الطلاب إلى استثمارها في الدراسة والمراجعة، وأسأل الله أن يبارك في هذا العمل وأن ينفع به الجميع."
  },
  {
   "id": "a3",
   "name": "أ/عبدالحميد الخن",
   "role": "معلم الكيمياء",
   "msg": "أقدّم هذه المنصة لطلابي ولكل من يطلب العلم، وقد صمّمتُ نماذج المحاكاة فيها بنفسي بصفتي معلمًا للكيمياء، لتحويل المفاهيم المجرّدة إلى تجارب محسوسة يفهمها الطالب ويراها أمامه.\n\nهذا العمل وقفٌ في سبيل الله، أسأل الله أن يجعله خالصًا لوجهه الكريم وأن ينفع به كل من استخدمه، وأن يكتب لي ولكل من أعان عليه أجره.\n\nوحفاظًا على الأمانة العلمية، جميع الحقوق محفوظة للمصمّم أ/ عبدالحميد الخن. الاستخدام التعليمي متاح مجانًا داخل المنصة، ولا يجوز بيع النماذج أو إعادة نشرها أو نسخها أو التعديل عليها أو استخدامها لأغراض تجارية إلا بإذن كتابي مسبق مني.",
   "photo": "data:image/jpeg;base64,",
   "cat": "teacher",
   "subject": "55959295",
   "email": "abdelhamed.elkhen@gmail.com"
  }
 ],
